#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: release signing + Play upload credentials → GitHub Actions secrets.
# ──────────────────────────────────────────────────────────────────────────
#
# Run from any checkout:  just release-secrets   (or tool/release_secrets.sh)
#
# Sets the three secrets .github/workflows/release.yml needs, besides
# CARTO_API_KEY (`just carto-key`):
#   ANDROID_KEYSTORE_BASE64  the upload keystore, base64
#   ANDROID_KEY_PROPERTIES   android/key.properties, storeFile pinned to the
#                            path the workflow decodes the keystore to
#   PLAY_STORE_JSON_KEY      a Google Cloud service-account JSON key with
#                            release rights on the app in Play Console
# Nothing is printed or put in argv: every secret goes to `gh secret set` from
# a file or a pipe, and passwords reach keytool through the environment.

PACKAGE=dk.alexanderlhc.walkable
REPO_ROOT=$(git rev-parse --show-toplevel)
# The first `git worktree list` entry is the main checkout.
MAIN_ROOT=$(git worktree list --porcelain | sed -n '1s/^worktree //p')
PLAY_JSON_NAME=play-store-key.json

# set_secret_from NAME < input: like set_secret, but the value comes from
# stdin (a file or a pipe), never from a shell variable or argv.
set_secret_from() {
  local name="$1"
  if gh secret set "$name" >/dev/null; then
    WRITTEN_SECRET+=("$name")
    printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
  else
    SKIPPED+=("GitHub secret $name (re-run this wizard)")
    warn "couldn't set GitHub secret $name"
  fi
}

# secret_exists NAME: whether the repo already has that Actions secret. Exits
# if gh can't list them, rather than treating every secret as missing.
secret_exists() {
  local names
  names=$(gh secret list --json name -q '.[].name') || { warn "gh secret list failed"; exit 1; }
  grep -qxF "$1" <<<"$names"
}

# prop KEY FILE: one value from a .properties file (the part after the first =).
prop() { sed -n "s/^$1=//p" "$2" | tail -n1; }

run_wizard() {

TOTAL_STAGES=6

command -v gh >/dev/null && gh auth status >/dev/null 2>&1 \
  || { warn "gh isn't logged in: run 'gh auth login' first"; exit 1; }

banner "Play Store release secrets"

# ──────────────────────────────────────────────────────────────────────────
stage "Upload keystore + key.properties"
say "The release workflow signs the bundle with the same upload key you use"
say "locally. We'll read android/key.properties and the keystore it points to,"
say "check the passwords open it, and upload both. Nothing is shown."
say ""
KP=""
for root in "$REPO_ROOT" "$MAIN_ROOT"; do
  [[ -f "$root/android/key.properties" ]] && { KP="$root/android/key.properties"; break; }
done
[[ -n "$KP" ]] || { warn "no android/key.properties in $REPO_ROOT or $MAIN_ROOT"; exit 1; }
note "key.properties: $KP"
for k in storeFile storePassword keyAlias keyPassword; do
  [[ -n "$(prop "$k" "$KP")" ]] || { warn "$k is missing or empty in $KP"; exit 1; }
done
KS=$(prop storeFile "$KP")
# Gradle resolves a relative storeFile against android/app.
[[ "$KS" == /* ]] || KS="$(dirname "$KP")/app/$KS"
[[ -f "$KS" ]] || { warn "keystore not found: $KS"; exit 1; }
note "keystore:       $KS"
if STOREPASS=$(prop storePassword "$KP") keytool -list -keystore "$KS" -alias "$(prop keyAlias "$KP")" \
     -storepass:env STOREPASS >/dev/null 2>&1; then
  printf '  %s✓ keystore opens%s and holds the key alias\n' "$GREEN" "$RESET"
else
  warn "keytool couldn't open the keystore with storePassword, or the alias is missing"
  confirm "Upload them anyway?" || exit 1
fi
say ""
if { secret_exists ANDROID_KEYSTORE_BASE64 && secret_exists ANDROID_KEY_PROPERTIES; } \
   && ! confirm "Both secrets already exist. Overwrite them?"; then
  note "kept the existing ANDROID_KEYSTORE_BASE64 and ANDROID_KEY_PROPERTIES"
else
  # Process substitution, not a pipe, so set_secret_from runs in this shell
  # and its summary entries survive.
  set_secret_from ANDROID_KEYSTORE_BASE64 < <(base64 -w0 "$KS")
  # The workflow decodes the keystore to android/app/upload-keystore.jks.
  set_secret_from ANDROID_KEY_PROPERTIES < <(sed 's|^storeFile=.*|storeFile=upload-keystore.jks|' "$KP")
fi
pause

# ──────────────────────────────────────────────────────────────────────────
stage "Play upload key: already have one?"
PLAY_JSON=""
for root in "$REPO_ROOT" "$MAIN_ROOT"; do
  [[ -f "$root/$PLAY_JSON_NAME" ]] && { PLAY_JSON="$root/$PLAY_JSON_NAME"; break; }
done
if [[ -n "$PLAY_JSON" ]] && confirm "Found $PLAY_JSON. Use it and skip the Google Cloud steps?"; then
  SKIP_GOOGLE=1
  TOTAL_STAGES=3 # the three Google stages are skipped
else
  PLAY_JSON=""
  SKIP_GOOGLE=0
  say "Next: a Google Cloud service account that may publish $PACKAGE,"
  say "and a JSON key for it. Three stages: project + API, account + key,"
  say "Play Console access. Have the Google account that owns the Play"
  say "developer account signed in to the browser."
fi
pause

if (( ! SKIP_GOOGLE )); then
# ──────────────────────────────────────────────────────────────────────────
stage "Google Cloud: project + Play Developer API"
say "Any Google Cloud project works; Play no longer needs it linked."
open_url "https://console.cloud.google.com/projectcreate"
step "Name it e.g. walkable-release, no organization → Create."
note "    (Or reuse a project you already have, and skip creating one.)"
pause "Got the project? Press Enter to enable the API"
open_url "https://console.cloud.google.com/apis/library/androidpublisher.googleapis.com"
step "Pick the project in the top project picker."
step "Click Enable. (\"Manage\" instead of Enable means it's already on.)"
pause

# ──────────────────────────────────────────────────────────────────────────
stage "Google Cloud: service account + JSON key"
open_url "https://console.cloud.google.com/iam-admin/serviceaccounts"
step "Same project. Click + Create service account."
step "Name: walkable-release. Click Done. Skip \"Create and continue\""
note "    (it asks for Cloud IAM roles, and Play doesn't need any)."
step "Copy the account's email (…@<project>.iam.gserviceaccount.com)."
ask SA_EMAIL "Paste the service account email:"
say ""
step "Click the account → Keys tab → Add key → Create new key → JSON → Create."
note "    The browser downloads the .json file. It's a password: don't share it."
note "    \"Key creation is disabled\" means an org policy blocks it"
note "    (iam.disableServiceAccountKeyCreation). Use a project with no organization."
say ""
newest=$(ls -t "$HOME"/Downloads/*.json 2>/dev/null | head -n1 || true)
[[ -n "$newest" ]] && note "Newest JSON in ~/Downloads: $newest"
ask JSON_PATH "Path to the downloaded JSON key (Enter = newest above):"
JSON_PATH=${JSON_PATH:-$newest}
JSON_PATH=${JSON_PATH/#\~/$HOME}
[[ -f "$JSON_PATH" ]] || { warn "no such file: $JSON_PATH"; exit 1; }
PLAY_JSON="$MAIN_ROOT/$PLAY_JSON_NAME"
if [[ -f "$PLAY_JSON" ]] && ! confirm "Replace the existing $PLAY_JSON with it?"; then exit 1; fi
(umask 077 && cp "$JSON_PATH" "$PLAY_JSON")
chmod 600 "$PLAY_JSON"
printf '  %s✓ saved%s %s (gitignored; local `fastlane deploy` reads it)\n' "$GREEN" "$RESET" "$PLAY_JSON"
note "You can now delete the copy in Downloads: $JSON_PATH"
pause

# ──────────────────────────────────────────────────────────────────────────
stage "Play Console: give the account release rights"
open_url "https://play.google.com/console"
step "Left menu: Users and permissions → Invite new users."
step "Email address: $SA_EMAIL"
step "App permissions tab → Add app → Walkable → Apply. Tick only:"
note "    • View app information and download bulk reports (read-only)"
note "    • Release to production, exclude devices, and use Play App Signing"
note "    • Release apps to testing tracks"
note "    Leave the Account permissions tab empty."
step "Apply → Invite user. (Service accounts don't need to accept it.)"
note "The first API call can fail for a while after the invite while Google"
note "propagates it; the check in the next stage tells you if that's still so."
pause
fi

# ──────────────────────────────────────────────────────────────────────────
stage "Check and upload the Play JSON key"
if python3 - "$PLAY_JSON" <<'PY'
import json, sys
d = json.load(open(sys.argv[1]))
assert d.get("type") == "service_account" and d.get("client_email") and d.get("private_key")
print("  service account:", d["client_email"])
PY
then
  printf '  %s✓ looks like a service-account key%s\n' "$GREEN" "$RESET"
else
  warn "$PLAY_JSON isn't a service-account JSON key"; exit 1
fi
if (cd "$REPO_ROOT/android" && bundle exec fastlane --version) >/dev/null 2>&1; then
  say "Asking Play whether it accepts the key…"
  if (cd "$REPO_ROOT/android" && bundle exec fastlane run validate_play_store_json_key \
        json_key:"$PLAY_JSON" >/dev/null 2>&1); then
    printf '  %s✓ Play accepts the key%s\n' "$GREEN" "$RESET"
  else
    warn "Play rejected the key. Check the invite in the previous stage; a fresh"
    warn "invite can take up to a day to start working. Re-run to check again."
    SKIPPED+=("confirm Play accepts the key: re-run just release-secrets")
  fi
else
  note "fastlane isn't installed here (cd android && bundle install), so I can't"
  note "ask Play about the key yet. The first release run checks it anyway."
fi
say ""
if secret_exists PLAY_STORE_JSON_KEY && ! confirm "PLAY_STORE_JSON_KEY already exists. Overwrite it?"; then
  note "kept the existing PLAY_STORE_JSON_KEY"
else
  set_secret_from PLAY_STORE_JSON_KEY < "$PLAY_JSON"
fi
pause "Press Enter to finish"

finish
for s in CARTO_API_KEY ANDROID_KEYSTORE_BASE64 ANDROID_KEY_PROPERTIES PLAY_STORE_JSON_KEY; do
  if secret_exists "$s"; then note "  ✓ $s"; else warn "missing secret $s"; fi
done
note "Cut a release: git tag v0.5.1 && git push origin v0.5.1 (→ internal track)"
}

run_wizard "$@"; exit
